{
  "name": "文件监视器",
  "name_en": "File Watcher",
  "manufacturer": "",
  "description": "用于监视实验计算机上指定目录中的文件变化并记录日志的软件工具，常用于跟踪成像或数据采集过程中生成的数据文件。",
  "description_en": "A software utility that monitors file changes in a specified directory and records logs, commonly used in laboratories to track files generated during imaging or data acquisition.",
  "tag_hints": [
    "file monitoring",
    "experiment data logging",
    "directory watch",
    "data acquisition workflow",
    "imaging file tracking"
  ],
  "actions": [
    {
      "action_name": "auto-filesInDirectory",
      "description": "列出目录中的文件。",
      "description_en": "List files in the directory."
    },
    {
      "action_name": "auto-updateList",
      "description": "更新监视文件列表。",
      "description_en": "Update the monitored file list."
    },
    {
      "action_name": "auto-run",
      "description": "启动文件监视。",
      "description_en": "Start file monitoring."
    },
    {
      "action_name": "auto-stop",
      "description": "停止文件监视。",
      "description_en": "Stop file monitoring."
    },
    {
      "action_name": "auto-removeFromList",
      "description": "从监视列表中移除文件。",
      "description_en": "Remove files from the monitored list."
    },
    {
      "action_name": "auto-startLog",
      "description": "开始记录日志。",
      "description_en": "Start logging."
    },
    {
      "action_name": "auto-addToLog",
      "description": "向日志中添加记录。",
      "description_en": "Add an entry to the log."
    },
    {
      "action_name": "auto-getLog",
      "description": "获取日志内容。",
      "description_en": "Get the log contents."
    },
    {
      "action_name": "auto-saveLog",
      "description": "保存日志。",
      "description_en": "Save the log."
    }
  ]
}

